INSERT INTO `users` (`id`, `name`, `email`, `password_hash`, `role`, `is_active`, `last_login_at`, `created_at`, `updated_at`) VALUES (1,'Tahoshin Islam','admin@leotechbd.com','$2b$12$hBn.H1/FpjEGBM2P/N1gqejMk6vB4prKc24Rgo5utMkrY6enX8NTC','super_admin',1,NULL,'2026-11-05 14:22:53','2026-11-05 14:22:53');
