INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (1,'seo','SEO','Search engine optimization','Own the results page before your competitors know it is a channel.','## Be found first, and stay there.\n\nWhere online visibility makes or breaks a business, SEO is the pivotal strategy. We improve your visibility on the results page, drive organic traffic that you do not pay per click for, and turn search intent into revenue.\n\n**What\'s included:** Keyword research, Competitor analysis, Content optimization, On-page SEO, Technical SEO, Backlink building, Local SEO, Global SEO.\n\n### Better user experience\n\nSearch engines reward what users reward: fast pages, clear structure, and content that answers the question. The technical and content work of SEO makes your site better for the humans who use it — and rankings follow.\n\n### Long-term, sustainable results\n\nPaid traffic stops the day the budget does. Rankings earned through disciplined SEO keep producing traffic and leads month after month, making it one of the most durable investments in the marketing stack.\n\n### Competitive advantage\n\nMost of your competitors are not optimizing seriously. Outranking them in search results captures market share from businesses that are actively looking for exactly what you sell — before those buyers ever see a competitor.',NULL,NULL,'[{\"title\":\"Increased visibility and traffic\",\"description\":\"Ranking on the first page puts you in front of buyers at the exact moment of intent. By optimizing your site for the keywords and phrases your customers actually use, we attract targeted organic traffic that converts into leads and sales — without paying for every click.\"},{\"title\":\"Credibility and trust\",\"description\":\"Websites that rank higher are perceived as more credible. Consistent, high-quality SEO establishes your authority in your industry, and that authority compounds: the longer you hold the position, the harder it is for competitors to displace you.\"},{\"title\":\"Targeted traffic, higher conversions\",\"description\":\"SEO lets you target the specific searches that signal buying intent. Visitors who arrive through them are far more likely to become customers, which is why organic traffic converts at rates paid channels struggle to match.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before seo shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'SEO services in Bangladesh | Leotech','Own the results page before your competitors know it is a channel. Where online visibility makes or breaks a business, SEO is the pivotal strategy. We improve y',NULL,NULL,0,'published','2026-11-05 14:22:53',10,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (2,'meta-marketing','Meta marketing','Meta & social marketing','Facebook and Instagram with a thesis — reach, engagement, conversion.','## One toolbox. Every platform working together.\n\nMeta marketing combines your channels — social, email, website, ads — into one machine instead of a set of disconnected tools. Facebook, Instagram, LinkedIn, and YouTube each get content built for how their audience actually behaves.\n\n### Brand authority and thought leadership\n\nConsistent presence and genuinely useful content position you as the authoritative voice in your niche. Authority earns trust, and trust shortens every sales cycle that follows.\n\n### Customer insights and market research\n\nAnalytics and social listening reveal what your audience prefers, feels, and does. Those insights feed back into strategy — content, offers, and timing all get smarter with every cycle.\n\n### Community and advocacy\n\nTwo-way communication and user-generated content turn customers into advocates. Advocates amplify your message, drive word-of-mouth referrals, and lower your cost of growth.',NULL,NULL,'[{\"title\":\"Expanded reach and visibility\",\"description\":\"We extend your reach far beyond traditional boundaries — Facebook, Instagram, LinkedIn, and more — so your message finds the right audience across demographics, interests, and geography.\"},{\"title\":\"Engagement and interaction\",\"description\":\"Compelling content tailored to each platform sparks conversations and builds a loyal community around your brand — polls, stories, live moments, and content people actually want to share.\"},{\"title\":\"Targeted advertising\",\"description\":\"Platform targeting by demographics, interests, and behavior means your ad spend lands on the people most likely to buy. We optimize continuously so every campaign gets sharper, not staler.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before meta marketing shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Meta marketing services in Bangladesh | Leotech','Facebook and Instagram with a thesis — reach, engagement, conversion. Meta marketing combines your channels — social, email, website, ads — into one machine ins',NULL,NULL,0,'published','2026-11-05 14:22:53',20,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (3,'google-ads','Google Ads','Google Ads','Data-driven PPC. Every taka accountable to blended ROAS.','## Paid attention, precisely spent.\n\nPPC puts you at the top of the page the moment someone searches for what you sell — and you pay only when they act. We run it as a data discipline, not a bidding lottery.\n\n### Our approach\n\nKeyword and competitor research set the map; tight ad groups, relevant copy, and landing-page alignment raise quality scores and lower cost per click. Then continuous testing reallocates budget toward what converts.\n\n### Measurable ROI\n\nEvery campaign reports to one number: return on ad spend. You see exactly what was spent, what came back, and what we changed — so advertising dollars are spent like investments, not hopes.',NULL,NULL,'[{\"title\":\"How PPC works\",\"description\":\"Your ad appears at the top of the results page for the searches you choose, and you pay only when someone clicks. Position is earned by relevance and quality, not just budget — which is where disciplined management pays off.\"},{\"title\":\"The benefits\",\"description\":\"Immediate visibility while SEO compounds, precise control over spend, and complete measurement from click to sale. PPC is the fastest lever for testing offers and filling the pipeline on demand.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before google ads shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Google Ads services in Bangladesh | Leotech','Data-driven PPC. Every taka accountable to blended ROAS. PPC puts you at the top of the page the moment someone searches for what you sell — and you pay only wh',NULL,NULL,0,'published','2026-11-05 14:22:53',30,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (4,'email-marketing','Email marketing','Email marketing','ROI-driven lists, segments, and automations that sell while you sleep.','## The channel you own outright.\n\nNo algorithm sits between you and your list. Done properly, email is the highest-ROI channel in the stack — a direct line to the people who already raised their hand.\n\n### Automating your campaigns\n\nWelcome series, abandoned-cart recovery, re-engagement flows — automations that sell around the clock and get better as the data accumulates.\n\n### Analyzing and optimizing\n\nOpens, clicks, conversions, and revenue per send are reviewed on every campaign. What works gets scaled; what does not gets cut. The list gets more valuable every month.',NULL,NULL,'[{\"title\":\"Building your list\",\"description\":\"We grow a permission-based list of people who actually want to hear from you — lead magnets, site capture, and offline touchpoints — because a list you own beats an audience you rent.\"},{\"title\":\"Creating engaging content\",\"description\":\"Newsletters, offers, and lifecycle emails written to be opened. Subject lines earn the click; content earns the next open. No noise, no spam-bait.\"},{\"title\":\"Segmenting your audience\",\"description\":\"Not every customer is the same, so no one gets the same message. Segments by behavior, purchase history, and interest lift open rates and conversions in every send.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before email marketing shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Email marketing services in Bangladesh | Leotech','ROI-driven lists, segments, and automations that sell while you sleep. No algorithm sits between you and your list. Done properly, email is the highest-ROI chan',NULL,NULL,0,'published','2026-11-05 14:22:53',40,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (5,'influencer-marketing','Influencer marketing','Influencer marketing','The right voices for your niche — trust, borrowed and then earned.','## Trust, at scale.\n\nPeople trust recommendations from voices they follow. We match your brand with the right creators — fashion on Instagram, gaming on YouTube, everything between — and measure what their audience does next.\n\n### Trust and credibility\n\nA recommendation from a trusted voice transfers credibility to your brand in a way an ad cannot. It is the closest thing to word-of-mouth that can be planned, briefed, and measured.',NULL,NULL,'[{\"title\":\"How it works\",\"description\":\"We find creators whose audience matches your target customer — celebrities, niche experts, or micro-influencers — and manage the collaboration end to end: briefs, content, rights, and reporting.\"},{\"title\":\"Engagement and sales\",\"description\":\"When the right voice shares your product, their followers click, buy, and engage. We track the full path so you know the return on every partnership and can double down on what performs.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before influencer marketing shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Influencer marketing services in Bangladesh | Leotech','The right voices for your niche — trust, borrowed and then earned. People trust recommendations from voices they follow. We match your brand with the right crea',NULL,NULL,0,'published','2026-11-05 14:22:53',50,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (6,'content-and-video','Content & video','In-house studio','In-house studio: product stills, videos, and explainers that convert.','## Content that sells before anyone reads a word.\n\nOur in-house studio produces product stills, product films and explainer videos built for the platforms your customers use.\n\n### Explainer videos\n\nComplex offers made simple. Explainers that answer the questions your customers were about to ask — before they ask a competitor.',NULL,NULL,'[{\"title\":\"Product images\",\"description\":\"The face of your product online. High-resolution, well-lit, shot from every angle that matters — so customers decide in your favor before reading a word.\"},{\"title\":\"Product videos\",\"description\":\"Your product, in motion — features, benefits, and the moment of use, cut to hold attention and drive conversion on every platform.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before content & video shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Content & video services in Bangladesh | Leotech','In-house studio: product stills, videos, and explainers that convert. Our in-house studio produces product stills, product films and explainer videos built for ',NULL,NULL,0,'published','2026-11-05 14:22:53',60,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (7,'web-and-ui-ux','Web & UI/UX','Web, brand & UI/UX','Sites engineered to convert — fast, seamless, unmistakably yours.','## A storefront that is open around the clock.\n\nBrand identity, interface design and fast, SEO-friendly websites engineered to convert visitors into customers.\n\n### Website development\n\nYour website is your digital storefront, open around the clock. We build fast, secure, SEO-friendly sites with clear calls to action and seamless journeys — the best sales asset your business will own.\n\n### Mobile friendliness\n\nMost of Bangladesh browses on a phone. Responsive design that adapts to every device is not a feature, it is the baseline — and it directly affects both your search rankings and your conversion rate.',NULL,NULL,'[{\"title\":\"Brand identity\",\"description\":\"Values, mission, and vision form the foundation; personality, messaging, and story make it human. We define the essence that sets you apart and carry it consistently through every touchpoint your customers meet.\"},{\"title\":\"Logo design\",\"description\":\"Your logo is the first visual element most customers encounter — it must capture attention, convey professionalism, and hold up everywhere from a business card to a billboard. We design marks that are distinctive, versatile, and built to become synonymous with your brand.\"},{\"title\":\"UI/UX design\",\"description\":\"A seamless experience keeps visitors engaged and moves them toward action. Intuitive navigation, clear layout, and interfaces optimized for every screen size — because first impressions are made in seconds and conversions are won in the details.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before web & ui/ux shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Web & UI/UX services in Bangladesh | Leotech','Sites engineered to convert — fast, seamless, unmistakably yours. Brand identity, interface design and fast, SEO-friendly websites engineered to convert visitor',NULL,NULL,0,'published','2026-11-05 14:22:53',70,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
INSERT INTO `services` (`id`, `slug`, `title`, `eyebrow`, `summary`, `body`, `hero_image`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `og_image`, `canonical_url`, `noindex`, `status`, `published_at`, `sort_order`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (8,'online-pr-and-inbound','Online PR & inbound','Online PR & inbound','Reputation, publicity, and content that pulls customers to you.','## Reputation that pulls, not pushes.\n\nOnline PR manages how the internet talks about you; inbound marketing gives people a reason to come to you. Together they build the authority that paid media alone cannot buy.\n\n### Attracting with valuable content\n\nInbound flips the funnel: instead of interrupting people, we publish content that answers their questions — blogs, guides, videos — and positions you as the helpful expert in the room.\n\n### Converting leads into customers\n\nVisitors who engage with your content become leads through sign-ups, trials, and offers. Nurture sequences then move them from curious to customer at their pace, not ours.\n\n### Measurable results and ROI\n\nClear objectives and tracked KPIs mean you always know what reputation and content work is returning — and resources go where the outcomes are.',NULL,NULL,'[{\"title\":\"Brand reputation management\",\"description\":\"We monitor and shape how your business appears across the internet — reviews, mentions, forums, and press — addressing concerns before they become stories and amplifying the wins.\"},{\"title\":\"Content creation and distribution\",\"description\":\"Positive, useful information about your business placed where your audience already reads: online publications, blogs, and industry channels that carry weight.\"},{\"title\":\"Credibility and trust\",\"description\":\"Third-party coverage builds a kind of trust that advertising cannot buy. Consistent online PR compounds into an authority position competitors have to earn the slow way.\"}]','[{\"title\":\"Discover\",\"description\":\"We audit your market, competitors and current numbers so the plan starts from evidence, not assumptions.\"},{\"title\":\"Plan\",\"description\":\"A channel plan with targets, budget allocation and the one metric each activity reports to.\"},{\"title\":\"Launch\",\"description\":\"Campaigns, content and pages go live with tracking verified end to end.\"},{\"title\":\"Optimise\",\"description\":\"Weekly reviews move budget toward what converts and cut what does not.\"}]','[{\"question\":\"How long before online pr & inbound shows results?\",\"answer\":\"Most clients see leading indicators within the first month and measurable revenue impact within one quarter. We agree targets up front and report against them every week.\"},{\"question\":\"Do you work with small businesses?\",\"answer\":\"Yes. Plans scale from a single channel for a growing business to a full-funnel programme for established brands.\"}]','Book a free consultation',NULL,'Online PR & inbound services in Bangladesh | Leotech','Reputation, publicity, and content that pulls customers to you. Online PR manages how the internet talks about you; inbound marketing gives people a reason to c',NULL,NULL,0,'published','2026-11-05 14:22:53',80,1,1,'2026-11-05 14:22:53','2026-11-05 14:22:53');
