DROP TABLE IF EXISTS `service_translations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `service_translations` (
  `service_id` int(10) unsigned NOT NULL,
  `locale` varchar(10) NOT NULL,
  `title` varchar(160) DEFAULT NULL,
  `eyebrow` varchar(120) DEFAULT NULL,
  `summary` varchar(500) DEFAULT NULL,
  `body` mediumtext DEFAULT NULL,
  `hero_image_alt` varchar(250) DEFAULT NULL,
  `features` longtext DEFAULT NULL,
  `process_steps` longtext DEFAULT NULL,
  `faqs` longtext DEFAULT NULL,
  `cta_label` varchar(80) DEFAULT NULL,
  `price_from` varchar(80) DEFAULT NULL,
  `seo_title` varchar(70) DEFAULT NULL,
  `seo_description` varchar(170) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`service_id`,`locale`),
  KEY `fk_translations_user` (`updated_by`),
  CONSTRAINT `fk_translations_service` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_translations_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `service_translations` WRITE;
/*!40000 ALTER TABLE `service_translations` DISABLE KEYS */;
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (1,'bn','এসইও','সার্চ ইঞ্জিন অপটিমাইজেশন','প্রতিযোগীরা টের পাওয়ার আগেই সার্চ রেজাল্টের প্রথম পাতা দখল করুন।','## সবার আগে খুঁজে পাওয়া যান, আর সেখানেই থাকুন।\n\nযেখানে অনলাইন ভিজিবিলিটিই ব্যবসার ভাগ্য নির্ধারণ করে, সেখানে এসইও সবচেয়ে গুরুত্বপূর্ণ কৌশল। আমরা সার্চ রেজাল্টে আপনার উপস্থিতি বাড়াই, এমন অর্গানিক ট্রাফিক আনি যার প্রতি ক্লিকে টাকা দিতে হয় না, আর সার্চের আগ্রহকে রূপ দিই আয়ে।\n\n**যা থাকছে:** কিওয়ার্ড রিসার্চ, প্রতিযোগী বিশ্লেষণ, কনটেন্ট অপটিমাইজেশন, অন-পেজ এসইও, টেকনিক্যাল এসইও, ব্যাকলিংক বিল্ডিং, লোকাল এসইও, গ্লোবাল এসইও।\n\n### উন্নত ইউজার এক্সপেরিয়েন্স\n\nব্যবহারকারী যা পছন্দ করে, সার্চ ইঞ্জিনও তা-ই পুরস্কৃত করে: দ্রুত পেজ, স্পষ্ট কাঠামো, আর প্রশ্নের সঠিক উত্তর দেওয়া কনটেন্ট। এসইওর টেকনিক্যাল ও কনটেন্টের কাজ আপনার সাইটকে মানুষের জন্য আরও ভালো করে — র‍্যাঙ্কিং আসে তার পরে।\n\n### দীর্ঘমেয়াদি, টেকসই ফলাফল\n\nবাজেট বন্ধ হলেই পেইড ট্রাফিক বন্ধ। নিয়মিত এসইওতে অর্জিত র‍্যাঙ্কিং মাসের পর মাস ট্রাফিক ও লিড এনে দেয় — তাই মার্কেটিং স্ট্যাকে এটি সবচেয়ে টেকসই বিনিয়োগগুলোর একটি।\n\n### প্রতিযোগিতায় সুবিধা\n\nআপনার বেশিরভাগ প্রতিযোগী সিরিয়াসভাবে অপটিমাইজ করছে না। সার্চ রেজাল্টে তাদের ছাড়িয়ে গেলে আপনি সেই ব্যবসাগুলোর বাজার দখল করেন যারা ঠিক আপনার পণ্যই খুঁজছে — প্রতিযোগীকে দেখার আগেই।',NULL,'[{\"title\":\"বাড়তি ভিজিবিলিটি ও ট্রাফিক\",\"description\":\"প্রথম পাতায় র‍্যাঙ্ক করলে ঠিক কেনার মুহূর্তে আপনি ক্রেতার সামনে থাকেন। গ্রাহকরা যে কিওয়ার্ড ও বাক্যাংশ সত্যিই ব্যবহার করেন, সেগুলোর জন্য সাইট অপটিমাইজ করে আমরা টার্গেটেড অর্গানিক ট্রাফিক আনি — যা প্রতিটি ক্লিকের জন্য টাকা না দিয়েই লিড ও বিক্রিতে রূপ নেয়।\"},{\"title\":\"বিশ্বাসযোগ্যতা ও আস্থা\",\"description\":\"যে ওয়েবসাইট ওপরে র‍্যাঙ্ক করে, মানুষ তাকে বেশি বিশ্বাসযোগ্য মনে করে। ধারাবাহিক, মানসম্মত এসইও আপনার ইন্ডাস্ট্রিতে কর্তৃত্ব প্রতিষ্ঠা করে, আর সেই কর্তৃত্ব সময়ের সঙ্গে বাড়ে: যত বেশি সময় অবস্থান ধরে রাখবেন, প্রতিযোগীর পক্ষে আপনাকে সরানো তত কঠিন।\"},{\"title\":\"টার্গেটেড ট্রাফিক, বেশি কনভার্শন\",\"description\":\"এসইও দিয়ে আপনি ঠিক সেই সার্চগুলো টার্গেট করতে পারেন যা কেনার ইচ্ছা প্রকাশ করে। এসব সার্চ থেকে আসা ভিজিটরের গ্রাহক হওয়ার সম্ভাবনা অনেক বেশি — এ কারণেই অর্গানিক ট্রাফিক এমন হারে কনভার্ট করে, যা পেইড চ্যানেলের পক্ষে মেলানো কঠিন।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"এসইও থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'এসইও সার্ভিস, বাংলাদেশ | লিওটেক','প্রতিযোগীরা টের পাওয়ার আগেই সার্চ রেজাল্টের প্রথম পাতা দখল করুন। যেখানে অনলাইন ভিজিবিলিটিই ব্যবসার ভাগ্য নির্ধারণ করে, সেখানে এসইও সবচেয়ে গুরুত্বপূর্ণ কৌশল। আ',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (2,'bn','মেটা মার্কেটিং','মেটা ও সোশ্যাল মার্কেটিং','পরিকল্পিত ফেসবুক ও ইনস্টাগ্রাম — রিচ, এনগেজমেন্ট, কনভার্শন।','## একটি টুলবক্স। প্রতিটি প্ল্যাটফর্ম একসঙ্গে কাজ করে।\n\nমেটা মার্কেটিং আপনার চ্যানেলগুলো — সোশ্যাল, ইমেইল, ওয়েবসাইট, বিজ্ঞাপন — বিচ্ছিন্ন টুলের বদলে একটি যন্ত্রে মিলিয়ে দেয়। ফেসবুক, ইনস্টাগ্রাম, লিংকডইন আর ইউটিউব প্রতিটি পায় তার দর্শকের আচরণ অনুযায়ী তৈরি কনটেন্ট।\n\n### ব্র্যান্ড অথরিটি ও থট লিডারশিপ\n\nধারাবাহিক উপস্থিতি আর সত্যিকারের কাজের কনটেন্ট আপনাকে নিজের নিশে কর্তৃত্বপূর্ণ কণ্ঠ হিসেবে প্রতিষ্ঠিত করে। কর্তৃত্ব আস্থা আনে, আর আস্থা প্রতিটি সেলস সাইকেলকে ছোট করে।\n\n### গ্রাহক ইনসাইট ও মার্কেট রিসার্চ\n\nঅ্যানালিটিক্স আর সোশ্যাল লিসেনিং জানায় আপনার দর্শক কী পছন্দ করে, কী অনুভব করে, কী করে। সেই ইনসাইট ফিরে যায় কৌশলে — কনটেন্ট, অফার আর সময় প্রতিটি ধাপে আরও বুদ্ধিদীপ্ত হয়।\n\n### কমিউনিটি ও অ্যাডভোকেসি\n\nদুই-মুখী যোগাযোগ আর ইউজার-জেনারেটেড কনটেন্ট গ্রাহককে বানায় আপনার প্রচারক। তারা বার্তা ছড়িয়ে দেয়, মুখে মুখে রেফারেল আনে, আর কমায় প্রবৃদ্ধির খরচ।',NULL,'[{\"title\":\"বিস্তৃত রিচ ও ভিজিবিলিটি\",\"description\":\"ফেসবুক, ইনস্টাগ্রাম, লিংকডইন সহ নানা প্ল্যাটফর্মে আমরা আপনার নাগাল প্রচলিত সীমার অনেক বাইরে নিয়ে যাই — যাতে বয়স, আগ্রহ আর ভৌগোলিক অবস্থান মিলিয়ে বার্তা পৌঁছায় সঠিক দর্শকের কাছে।\"},{\"title\":\"এনগেজমেন্ট ও ইন্টারঅ্যাকশন\",\"description\":\"প্রতিটি প্ল্যাটফর্মের উপযোগী আকর্ষণীয় কনটেন্ট কথোপকথন শুরু করে এবং ব্র্যান্ড ঘিরে একটি অনুগত কমিউনিটি গড়ে তোলে — পোল, স্টোরি, লাইভ, আর এমন কনটেন্ট যা মানুষ শেয়ার করতে চায়।\"},{\"title\":\"টার্গেটেড বিজ্ঞাপন\",\"description\":\"বয়স, আগ্রহ ও আচরণভিত্তিক টার্গেটিংয়ে আপনার বিজ্ঞাপনের টাকা খরচ হয় তাদের জন্য, যারা কেনার সম্ভাবনা সবচেয়ে বেশি। আমরা নিরন্তর অপটিমাইজ করি, তাই প্রতিটি ক্যাম্পেইন সময়ের সঙ্গে আরও ধারালো হয়।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"মেটা মার্কেটিং থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'মেটা মার্কেটিং সার্ভিস, বাংলাদেশ | লিওটেক','পরিকল্পিত ফেসবুক ও ইনস্টাগ্রাম — রিচ, এনগেজমেন্ট, কনভার্শন। মেটা মার্কেটিং আপনার চ্যানেলগুলো — সোশ্যাল, ইমেইল, ওয়েবসাইট, বিজ্ঞাপন — বিচ্ছিন্ন টুলের বদলে একটি য',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (3,'bn','গুগল অ্যাডস','গুগল অ্যাডস','ডেটানির্ভর পিপিসি। প্রতিটি টাকার হিসাব ব্লেন্ডেড ROAS-এ।','## মনোযোগ কেনা, নিখুঁত হিসাবে।\n\nকেউ আপনার পণ্য খোঁজার মুহূর্তেই পিপিসি আপনাকে পাতার শীর্ষে রাখে — আর টাকা দেন শুধু তারা কাজ করলে। আমরা এটি চালাই ডেটার শৃঙ্খলায়, বিডিংয়ের লটারি হিসেবে নয়।\n\n### আমাদের পদ্ধতি\n\nকিওয়ার্ড ও প্রতিযোগী রিসার্চ দিয়ে মানচিত্র তৈরি হয়; গোছানো অ্যাড গ্রুপ, প্রাসঙ্গিক কপি আর ল্যান্ডিং পেজের মিল কোয়ালিটি স্কোর বাড়ায়, কমায় প্রতি ক্লিকের খরচ। এরপর নিরন্তর টেস্টিং বাজেট সরিয়ে নেয় যা কনভার্ট করে সেদিকে।\n\n### পরিমাপযোগ্য ROI\n\nপ্রতিটি ক্যাম্পেইনের হিসাব একটি সংখ্যায়: রিটার্ন অন অ্যাড স্পেন্ড। আপনি সঠিকভাবে দেখতে পান কত খরচ হলো, কত ফিরল, আর আমরা কী বদলালাম — তাই বিজ্ঞাপনের টাকা খরচ হয় বিনিয়োগের মতো, আশার মতো নয়।',NULL,'[{\"title\":\"পিপিসি যেভাবে কাজ করে\",\"description\":\"আপনার বেছে নেওয়া সার্চের জন্য রেজাল্ট পাতার ওপরে বিজ্ঞাপন দেখায়, আর টাকা দেন শুধু কেউ ক্লিক করলে। অবস্থান নির্ধারণ হয় প্রাসঙ্গিকতা ও মানের ভিত্তিতে, শুধু বাজেটে নয় — আর এখানেই দক্ষ ম্যানেজমেন্টের ফল মেলে।\"},{\"title\":\"সুবিধাগুলো\",\"description\":\"এসইও বাড়তে বাড়তে তাৎক্ষণিক ভিজিবিলিটি, খরচের ওপর পূর্ণ নিয়ন্ত্রণ, আর ক্লিক থেকে বিক্রি পর্যন্ত পুরো পরিমাপ। অফার যাচাই আর চাহিদামতো পাইপলাইন ভরানোর সবচেয়ে দ্রুত উপায় পিপিসি।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"গুগল অ্যাডস থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'গুগল অ্যাডস সার্ভিস, বাংলাদেশ | লিওটেক','ডেটানির্ভর পিপিসি। প্রতিটি টাকার হিসাব ব্লেন্ডেড ROAS-এ। কেউ আপনার পণ্য খোঁজার মুহূর্তেই পিপিসি আপনাকে পাতার শীর্ষে রাখে — আর টাকা দেন শুধু তারা কাজ করলে। আমরা ',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (4,'bn','ইমেইল মার্কেটিং','ইমেইল মার্কেটিং','ROI-কেন্দ্রিক লিস্ট, সেগমেন্ট আর অটোমেশন — আপনি ঘুমালেও বিক্রি চলে।','## যে চ্যানেলের মালিক পুরোপুরি আপনি।\n\nআপনার আর আপনার লিস্টের মাঝে কোনো অ্যালগরিদম নেই। ঠিকভাবে করলে ইমেইলই মার্কেটিং স্ট্যাকের সর্বোচ্চ ROI-এর চ্যানেল — যারা আগেই আগ্রহ দেখিয়েছেন, তাদের সঙ্গে সরাসরি যোগাযোগ।\n\n### ক্যাম্পেইন অটোমেশন\n\nওয়েলকাম সিরিজ, অ্যাবানডনড কার্ট রিকভারি, রি-এনগেজমেন্ট ফ্লো — এমন অটোমেশন যা চব্বিশ ঘণ্টা বিক্রি করে, আর ডেটা জমার সঙ্গে আরও ভালো হয়।\n\n### বিশ্লেষণ ও অপটিমাইজেশন\n\nপ্রতিটি ক্যাম্পেইনে ওপেন, ক্লিক, কনভার্শন আর প্রতি পাঠানোয় আয় পর্যালোচনা হয়। যা কাজ করে তা বাড়ানো হয়; যা করে না তা বাদ। প্রতি মাসে লিস্টের মূল্য বাড়ে।',NULL,'[{\"title\":\"লিস্ট তৈরি\",\"description\":\"আমরা এমন মানুষের অনুমতিভিত্তিক লিস্ট গড়ি যারা সত্যিই আপনার কাছ থেকে শুনতে চায় — লিড ম্যাগনেট, সাইট ক্যাপচার আর অফলাইন টাচপয়েন্টের মাধ্যমে। কারণ নিজের লিস্ট ভাড়া করা দর্শকের চেয়ে অনেক মূল্যবান।\"},{\"title\":\"আকর্ষণীয় কনটেন্ট\",\"description\":\"নিউজলেটার, অফার আর লাইফসাইকেল ইমেইল যা খোলার জন্যই লেখা। সাবজেক্ট লাইন ক্লিক আনে; কনটেন্ট আনে পরের ওপেন। কোনো বাড়তি শব্দ নয়, স্প্যামের ফাঁদ নয়।\"},{\"title\":\"দর্শক সেগমেন্টেশন\",\"description\":\"সব গ্রাহক এক নয়, তাই সবাই একই বার্তা পায় না। আচরণ, কেনার ইতিহাস আর আগ্রহভিত্তিক সেগমেন্ট প্রতিটি পাঠানোয় ওপেন রেট ও কনভার্শন বাড়ায়।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"ইমেইল মার্কেটিং থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'ইমেইল মার্কেটিং সার্ভিস, বাংলাদেশ | লিওটেক','ROI-কেন্দ্রিক লিস্ট, সেগমেন্ট আর অটোমেশন — আপনি ঘুমালেও বিক্রি চলে। আপনার আর আপনার লিস্টের মাঝে কোনো অ্যালগরিদম নেই। ঠিকভাবে করলে ইমেইলই মার্কেটিং স্ট্যাকের সর্',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (5,'bn','ইনফ্লুয়েন্সার মার্কেটিং','ইনফ্লুয়েন্সার মার্কেটিং','আপনার নিশের জন্য সঠিক কণ্ঠ — ধার করা আস্থা, পরে নিজের অর্জন।','## আস্থা, বড় পরিসরে।\n\nমানুষ তাদের অনুসরণ করা কণ্ঠের সুপারিশে বিশ্বাস করে। আমরা আপনার ব্র্যান্ডকে মেলাই সঠিক ক্রিয়েটরের সঙ্গে — ইনস্টাগ্রামে ফ্যাশন, ইউটিউবে গেমিং, আর এর মাঝের সবকিছু — এবং মাপি তাদের দর্শক এরপর কী করে।\n\n### আস্থা ও বিশ্বাসযোগ্যতা\n\nবিশ্বস্ত কণ্ঠের সুপারিশ আপনার ব্র্যান্ডে এমন বিশ্বাসযোগ্যতা আনে যা বিজ্ঞাপন পারে না। মুখে মুখে প্রচারের সবচেয়ে কাছের জিনিস এটাই — যা পরিকল্পনা, ব্রিফ আর পরিমাপ করা যায়।',NULL,'[{\"title\":\"যেভাবে কাজ করে\",\"description\":\"আমরা এমন ক্রিয়েটর খুঁজে বের করি যাদের দর্শক আপনার টার্গেট গ্রাহকের সঙ্গে মেলে — সেলিব্রিটি, নিশ এক্সপার্ট বা মাইক্রো-ইনফ্লুয়েন্সার — আর ব্রিফ, কনটেন্ট, স্বত্ব ও রিপোর্টিং সহ পুরো সহযোগিতা সামলাই।\"},{\"title\":\"এনগেজমেন্ট ও বিক্রি\",\"description\":\"সঠিক কণ্ঠ যখন আপনার পণ্যের কথা বলে, তাদের ফলোয়াররা ক্লিক করে, কেনে, যুক্ত হয়। আমরা পুরো পথ ট্র্যাক করি, যাতে প্রতিটি পার্টনারশিপের রিটার্ন জানেন এবং যেটি ভালো করছে তাতে আরও বিনিয়োগ করতে পারেন।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"ইনফ্লুয়েন্সার মার্কেটিং থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'ইনফ্লুয়েন্সার মার্কেটিং সার্ভিস, বাংলাদেশ | লিওটেক','আপনার নিশের জন্য সঠিক কণ্ঠ — ধার করা আস্থা, পরে নিজের অর্জন। মানুষ তাদের অনুসরণ করা কণ্ঠের সুপারিশে বিশ্বাস করে। আমরা আপনার ব্র্যান্ডকে মেলাই সঠিক ক্রিয়েটরের স',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (6,'bn','কনটেন্ট ও ভিডিও','ইন-হাউস স্টুডিও','ইন-হাউস স্টুডিও: প্রোডাক্ট স্টিল, ভিডিও আর এক্সপ্লেইনার যা কনভার্ট করে।','## এমন কনটেন্ট যা একটি শব্দ পড়ার আগেই বিক্রি করে।\n\nআমাদের ইন-হাউস স্টুডিও আপনার গ্রাহকরা যে প্ল্যাটফর্ম ব্যবহার করেন, সেগুলোর জন্য প্রোডাক্ট স্টিল, প্রোডাক্ট ফিল্ম আর এক্সপ্লেইনার ভিডিও তৈরি করে।\n\n### এক্সপ্লেইনার ভিডিও\n\nজটিল অফার, সহজ করে। এমন এক্সপ্লেইনার যা গ্রাহকের প্রশ্নের উত্তর দেয় — তারা প্রতিযোগীকে জিজ্ঞেস করার আগেই।',NULL,'[{\"title\":\"প্রোডাক্ট ইমেজ\",\"description\":\"অনলাইনে আপনার পণ্যের চেহারা। হাই-রেজোলিউশন, ভালো আলোয়, প্রতিটি গুরুত্বপূর্ণ অ্যাঙ্গেল থেকে তোলা — যাতে একটি শব্দ পড়ার আগেই গ্রাহক আপনার পক্ষে সিদ্ধান্ত নেন।\"},{\"title\":\"প্রোডাক্ট ভিডিও\",\"description\":\"চলমান আপনার পণ্য — ফিচার, সুবিধা আর ব্যবহারের মুহূর্ত, প্রতিটি প্ল্যাটফর্মে মনোযোগ ধরে রাখতে আর কনভার্শন আনতে সম্পাদিত।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"কনটেন্ট ও ভিডিও থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'কনটেন্ট ও ভিডিও সার্ভিস, বাংলাদেশ | লিওটেক','ইন-হাউস স্টুডিও: প্রোডাক্ট স্টিল, ভিডিও আর এক্সপ্লেইনার যা কনভার্ট করে। আমাদের ইন-হাউস স্টুডিও আপনার গ্রাহকরা যে প্ল্যাটফর্ম ব্যবহার করেন, সেগুলোর জন্য প্রোডাক্',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (7,'bn','ওয়েব ও UI/UX','ওয়েব, ব্র্যান্ড ও UI/UX','কনভার্ট করার জন্য তৈরি সাইট — দ্রুত, নির্বিঘ্ন, একান্তই আপনার।','## এমন একটি দোকান যা খোলা থাকে চব্বিশ ঘণ্টা।\n\nব্র্যান্ড আইডেন্টিটি, ইন্টারফেস ডিজাইন আর দ্রুত, এসইও-বান্ধব ওয়েবসাইট — ভিজিটরকে গ্রাহকে রূপান্তরের জন্য তৈরি।\n\n### ওয়েবসাইট ডেভেলপমেন্ট\n\nআপনার ওয়েবসাইট আপনার ডিজিটাল দোকান, যা খোলা থাকে চব্বিশ ঘণ্টা। আমরা তৈরি করি দ্রুত, নিরাপদ, এসইও-বান্ধব সাইট — স্পষ্ট কল-টু-অ্যাকশন আর নির্বিঘ্ন যাত্রা সহ — আপনার ব্যবসার সেরা বিক্রয় সম্পদ।\n\n### মোবাইল ফ্রেন্ডলিনেস\n\nবাংলাদেশের বেশিরভাগ মানুষ ফোনে ব্রাউজ করেন। প্রতিটি ডিভাইসে মানিয়ে নেওয়া রেসপন্সিভ ডিজাইন কোনো বাড়তি ফিচার নয়, এটাই ন্যূনতম শর্ত — আর এটি সরাসরি আপনার সার্চ র‍্যাঙ্কিং ও কনভার্শন রেটকে প্রভাবিত করে।',NULL,'[{\"title\":\"ব্র্যান্ড আইডেন্টিটি\",\"description\":\"মূল্যবোধ, লক্ষ্য আর ভিশন হলো ভিত্তি; ব্যক্তিত্ব, বার্তা আর গল্প একে মানবিক করে। যা আপনাকে আলাদা করে, সেই মূল সত্তা আমরা নির্ধারণ করি এবং গ্রাহকের প্রতিটি টাচপয়েন্টে ধারাবাহিকভাবে পৌঁছে দিই।\"},{\"title\":\"লোগো ডিজাইন\",\"description\":\"বেশিরভাগ গ্রাহক প্রথম দেখে আপনার লোগো — তাই এটিকে মনোযোগ কাড়তে হবে, পেশাদারিত্ব প্রকাশ করতে হবে, আর ভিজিটিং কার্ড থেকে বিলবোর্ড সবখানে টিকে থাকতে হবে। আমরা এমন মার্ক ডিজাইন করি যা স্বতন্ত্র, বহুমুখী, আর আপনার ব্র্যান্ডের সমার্থক হয়ে ওঠে।\"},{\"title\":\"UI/UX ডিজাইন\",\"description\":\"নির্বিঘ্ন অভিজ্ঞতা ভিজিটরকে যুক্ত রাখে আর কাজের দিকে এগিয়ে দেয়। সহজ নেভিগেশন, স্পষ্ট লেআউট আর প্রতিটি স্ক্রিনের জন্য অপটিমাইজ করা ইন্টারফেস — কারণ প্রথম ধারণা তৈরি হয় সেকেন্ডে, আর কনভার্শন জেতা হয় খুঁটিনাটিতে।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"ওয়েব ও UI/UX থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'ওয়েব ও UI/UX সার্ভিস, বাংলাদেশ | লিওটেক','কনভার্ট করার জন্য তৈরি সাইট — দ্রুত, নির্বিঘ্ন, একান্তই আপনার। ব্র্যান্ড আইডেন্টিটি, ইন্টারফেস ডিজাইন আর দ্রুত, এসইও-বান্ধব ওয়েবসাইট — ভিজিটরকে গ্রাহকে রূপান্ত',1,'2026-11-05 14:22:53');
INSERT INTO `service_translations` (`service_id`, `locale`, `title`, `eyebrow`, `summary`, `body`, `hero_image_alt`, `features`, `process_steps`, `faqs`, `cta_label`, `price_from`, `seo_title`, `seo_description`, `updated_by`, `updated_at`) VALUES (8,'bn','অনলাইন পিআর ও ইনবাউন্ড','অনলাইন পিআর ও ইনবাউন্ড','সুনাম, প্রচার আর কনটেন্ট যা গ্রাহককে আপনার দিকে টানে।','## এমন সুনাম যা টানে, ঠেলে না।\n\nঅনলাইন পিআর নিয়ন্ত্রণ করে ইন্টারনেট আপনার সম্পর্কে কী বলে; ইনবাউন্ড মার্কেটিং মানুষকে আপনার কাছে আসার কারণ দেয়। দুটো মিলে গড়ে তোলে এমন কর্তৃত্ব, যা শুধু পেইড মিডিয়ায় কেনা যায় না।\n\n### মূল্যবান কনটেন্টে আকর্ষণ\n\nইনবাউন্ড ফানেলটাকে উল্টে দেয়: মানুষকে বিরক্ত না করে আমরা এমন কনটেন্ট প্রকাশ করি যা তাদের প্রশ্নের উত্তর দেয় — ব্লগ, গাইড, ভিডিও — এবং আপনাকে প্রতিষ্ঠিত করে সহায়ক বিশেষজ্ঞ হিসেবে।\n\n### লিডকে গ্রাহকে রূপান্তর\n\nযে ভিজিটর আপনার কনটেন্টে যুক্ত হয়, সাইন-আপ, ট্রায়াল আর অফারের মাধ্যমে সে লিড হয়। এরপর নার্চার সিকোয়েন্স তাকে তার নিজের গতিতে কৌতূহলী থেকে গ্রাহকে নিয়ে যায়।\n\n### পরিমাপযোগ্য ফলাফল ও ROI\n\nস্পষ্ট লক্ষ্য আর ট্র্যাক করা KPI মানে আপনি সবসময় জানেন সুনাম ও কনটেন্টের কাজ কী ফল দিচ্ছে — আর সম্পদ যায় যেখানে ফলাফল।',NULL,'[{\"title\":\"ব্র্যান্ড রেপুটেশন ম্যানেজমেন্ট\",\"description\":\"ইন্টারনেটে আপনার ব্যবসা কীভাবে উপস্থাপিত হয় — রিভিউ, উল্লেখ, ফোরাম আর প্রেস — আমরা তা নজরে রাখি ও গড়ে তুলি; সমস্যা খবর হওয়ার আগেই সমাধান করি, আর সাফল্যকে ছড়িয়ে দিই।\"},{\"title\":\"কনটেন্ট তৈরি ও বিতরণ\",\"description\":\"আপনার ব্যবসা সম্পর্কে ইতিবাচক, কাজের তথ্য পৌঁছে দিই সেখানে, যেখানে আপনার দর্শক আগে থেকেই পড়ে: প্রভাবশালী অনলাইন প্রকাশনা, ব্লগ আর ইন্ডাস্ট্রি চ্যানেলে।\"},{\"title\":\"বিশ্বাসযোগ্যতা ও আস্থা\",\"description\":\"থার্ড-পার্টি কভারেজ এমন আস্থা তৈরি করে যা বিজ্ঞাপনে কেনা যায় না। ধারাবাহিক অনলাইন পিআর ধীরে ধীরে এমন কর্তৃত্ব গড়ে, যা প্রতিযোগীকে কষ্ট করে অর্জন করতে হয়।\"}]','[{\"title\":\"জানা\",\"description\":\"আমরা আপনার বাজার, প্রতিযোগী আর বর্তমান সংখ্যাগুলো যাচাই করি, যাতে পরিকল্পনা শুরু হয় অনুমান থেকে নয়, প্রমাণ থেকে।\"},{\"title\":\"পরিকল্পনা\",\"description\":\"লক্ষ্য, বাজেট বণ্টন আর প্রতিটি কাজের জন্য একটি মূল মেট্রিক সহ চ্যানেল পরিকল্পনা।\"},{\"title\":\"লঞ্চ\",\"description\":\"ক্যাম্পেইন, কনটেন্ট আর পেজ লাইভ হয়, শুরু থেকে শেষ পর্যন্ত ট্র্যাকিং যাচাই করে।\"},{\"title\":\"অপটিমাইজ\",\"description\":\"সাপ্তাহিক পর্যালোচনায় বাজেট সরে যায় যা কনভার্ট করে সেদিকে, আর যা করে না তা বাদ পড়ে।\"}]','[{\"question\":\"অনলাইন পিআর ও ইনবাউন্ড থেকে ফল পেতে কত সময় লাগে?\",\"answer\":\"বেশিরভাগ ক্লায়েন্ট প্রথম মাসেই অগ্রগতির লক্ষণ দেখেন, আর এক প্রান্তিকের মধ্যে আয়ে পরিমাপযোগ্য প্রভাব। শুরুতেই আমরা লক্ষ্য ঠিক করি এবং প্রতি সপ্তাহে সেই অনুযায়ী রিপোর্ট দিই।\"},{\"question\":\"আপনারা কি ছোট ব্যবসার সঙ্গে কাজ করেন?\",\"answer\":\"হ্যাঁ। ছোট ব্যবসার জন্য একটি চ্যানেল থেকে শুরু করে প্রতিষ্ঠিত ব্র্যান্ডের ফুল-ফানেল প্রোগ্রাম পর্যন্ত প্ল্যান রয়েছে।\"}]','ফ্রি কনসালটেশন বুক করুন',NULL,'অনলাইন পিআর ও ইনবাউন্ড সার্ভিস, বাংলাদেশ | লিওটেক','সুনাম, প্রচার আর কনটেন্ট যা গ্রাহককে আপনার দিকে টানে। অনলাইন পিআর নিয়ন্ত্রণ করে ইন্টারনেট আপনার সম্পর্কে কী বলে; ইনবাউন্ড মার্কেটিং মানুষকে আপনার কাছে আসার কার',1,'2026-11-05 14:22:53');
